test("ratio equals difflib's, autojunk range included", () => {
  for (const { a, b, ratio: want } of REFERENCE) expect(ratio(a, b), `${a.slice(0, 30)} | ${b.slice(0, 30)}`).toBe(want);
});

test("round3 is Python's round(x, 3): half to even on a tie", () => {
  expect(round3(0.8125)).toBe(0.812);
  expect(round3(1)).toBe(1);
  expect(round3(0.12349)).toBe(0.123);
});

test("normalize lowercases, collapses Python whitespace and keeps 500 code points", () => {
  expect(normalize("  A B\u001cC \n")).toBe("a b c");
  expect(normalize(null)).toBe("");
  expect(Array.from(normalize("😀".repeat(600)).replaceAll(" ", "")).length).toBe(500);
});

test("score is 0 when a side normalizes to nothing but the join space still compares", () => {
  expect(score("t", "b", "t", "b")).toBe(1);
  expect(score(null, null, "x", "y")).toBe(ratio(" ", "x y"));
});

test("rank drops the target, applies the threshold, sorts high to low and keeps input order on ties", () => {
  const target = { number: 1, title: "Daemon crashes", body: "segfault on start" };
  const same = { number: 2, title: "Daemon crashes", body: "segfault on start" };
  const twin = { number: 3, title: "Daemon crashes", body: "segfault on start" };
  const near = { number: 4, title: "Daemon crashes", body: "segfault on start up" };
  const far = { number: 5, title: "Docs typo", body: "readme" };
  const got = rank(target, [target, near, far, same, twin], 0.8, 3);
  expect(got.map((r) => r.number)).toEqual([2, 3, 4]);
  expect(got[0]!.score).toBe(1);
});

test("round3 rounds the double's exact value, so 0.8075 (a hair under the tie) is 0.807 and a true tie is even", () => {
  expect(round3(0.8075)).toBe(0.807);
  expect(round3(0.0625)).toBe(0.062);
  expect(round3(0.0635)).toBe(0.064);
  expect(round3(0.5)).toBe(0.5);
});

test("rank follows the parent's order where scaled rounding put two candidates on the same score", () => {
  const title = "x";
  const target = { number: 1, title, body: "a".repeat(321) };
  const two = { number: 2, title, body: "a".repeat(321) + "b".repeat(154) };
  const three = { number: 3, title, body: "a".repeat(313) + "b".repeat(142) };
  const got = rank(target, [two, three], 0.5, 5);
  expect(got.map((g) => [g.number, g.score])).toEqual([[3, 0.808], [2, 0.807]]);
});
